<?php
declare(strict_types=1);
spl_autoload_register(function($c) { if (str_starts_with($c,'App\\')) require __DIR__.'/../app/'.str_replace('\\','/',substr($c,4)).'.php'; });
use App\Core\{Database, HrService, HrNotificationRecipients, HrWorkflowService, MailService};
use App\Core\Workflow\PushService;
$db=new PDO('sqlite::memory:',null,null,[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC]);
(new ReflectionProperty(Database::class,'instance'))->setValue(null,$db);
$db->exec("CREATE TABLE users(id INTEGER PRIMARY KEY,role_id INTEGER,is_active INTEGER,email TEXT);
 CREATE TABLE roles(id INTEGER PRIMARY KEY,name TEXT);
 CREATE TABLE employees(id INTEGER PRIMARY KEY,user_id INTEGER,manager_id INTEGER,file_status TEXT,full_name TEXT);
 CREATE TABLE org_positions(id INTEGER PRIMARY KEY,parent_id INTEGER,employee_id INTEGER,is_active INTEGER);
 CREATE TABLE notification_rules(event_type TEXT,is_active INTEGER,user_id INTEGER,role_id INTEGER);
 CREATE TABLE notifications(id INTEGER PRIMARY KEY,user_id INTEGER,title TEXT,body TEXT,link TEXT,sender_id INTEGER,is_announcement INTEGER,target_type TEXT,target_level INTEGER,target_role_id INTEGER,target_branch_id INTEGER,target_department_id INTEGER,broadcast_id INTEGER,entity_type TEXT,entity_id INTEGER,action_type TEXT,metadata_json TEXT);
 CREATE TABLE notification_queue(id INTEGER PRIMARY KEY,channel TEXT,user_id INTEGER,recipient TEXT,subject TEXT,body TEXT,link TEXT,entity_type TEXT,entity_id INTEGER,action_type TEXT);
 CREATE TABLE push_subscriptions(id INTEGER PRIMARY KEY,user_id INTEGER,endpoint TEXT,p256dh TEXT,auth TEXT,platform TEXT,user_agent TEXT,is_active INTEGER DEFAULT 1);
 CREATE TABLE internal_mails(id INTEGER PRIMARY KEY,sender_id INTEGER,subject TEXT,body TEXT);
 CREATE TABLE internal_mail_recipients(mail_id INTEGER,recipient_id INTEGER,UNIQUE(mail_id,recipient_id));
 CREATE TABLE internal_mail_targets(mail_id INTEGER,target_type TEXT,target_id INTEGER,target_label TEXT);
 INSERT INTO roles VALUES(1,'مدير قسم'),(2,'مدير قسم الموارد البشرية'),(3,'مدير النظام');
 INSERT INTO users VALUES(10,1,1,NULL),(20,1,1,NULL),(30,2,1,NULL),(40,1,0,NULL),(50,3,1,NULL);
 INSERT INTO employees VALUES(1,10,2,'open','employee'),(2,20,NULL,'open','manager'),(3,30,NULL,'open','HR'),(4,40,NULL,'open','inactive'),(5,NULL,4,'open','inactive manager team'),(6,NULL,NULL,'open','unassigned'),(7,NULL,7,'open','cycle');
 INSERT INTO org_positions VALUES(1,2,6,1),(2,NULL,2,1);");
$db->exec("ALTER TABLE employees ADD COLUMN status TEXT DEFAULT 'active'");
function check($ok,$message){if(!$ok)throw new RuntimeException($message);}
check(HrNotificationRecipients::manager(1)===20,'Direct manager only');
check(HrNotificationRecipients::manager(5)===null,'Inactive manager not notified');
check(HrNotificationRecipients::manager(6)===20,'Assigned org parent fallback');
check(HrNotificationRecipients::manager(2)===null,'No branch-wide fallback');
check(HrNotificationRecipients::teamEmployeeIds(20)===[1,6],'Evaluation reminders use assigned team, not broad HR visibility');
check(HrNotificationRecipients::teamEmployeeIds(30)===[],'HR sees no team reminder for unrelated employees');
check(HrNotificationRecipients::hr()===[30],'Only HR responsibility, not all managers or administrators');
foreach(['missing_clockin','missing_clockout','leave_request','advance_request','custody_due_soon','custody_overdue'] as $event){
 $db->prepare('INSERT INTO notification_rules VALUES (?,1,NULL,NULL),(?,1,50,1)')->execute([$event,$event]);
 check(HrService::notifyByLevel($event,1,'team alert','','/hr')===1,'Exactly one recipient despite duplicate/general rules: '.$event);
}
check($db->query('SELECT DISTINCT user_id FROM notifications')->fetchAll(PDO::FETCH_COLUMN)===[20],'Unrelated managers never notified');
check(HrService::notifyByLevel('disabled_event',1,'disabled','','/hr')===0,'Disabled event respected');
(new ReflectionMethod(HrWorkflowService::class,'notifyHrAboutHiring'))->invoke(null,['data'=>[]],9);
check((int)$db->query('SELECT user_id FROM notifications ORDER BY id DESC LIMIT 1')->fetchColumn()===30,'Hiring goes to HR only');
PushService::subscribe(10,['endpoint'=>'device-a','platform'=>'android']);
PushService::subscribe(10,['endpoint'=>'device-a','platform'=>'android']);
check(count(PushService::subscriptions(10))===1,'Idempotent same-account subscription');
PushService::subscribe(20,['endpoint'=>'device-a','platform'=>'ios']);
check(!PushService::hasSubscription(10) && count(PushService::subscriptions(20))===1,'Account switch transfers sole ownership');
PushService::unsubscribe(10,'device-a');
check(PushService::hasSubscription(20),'Old-account logout cannot unsubscribe new account');
$db->exec("INSERT INTO push_subscriptions(user_id,endpoint,platform) VALUES(10,'legacy-shared','android'),(20,'legacy-shared','android'),(10,'web-shared','web'),(20,'web-shared','web')");
check(!PushService::hasSubscription(10) && count(PushService::subscriptions(20))===1,'Ambiguous historical endpoints quarantined for all accounts and platforms');
PushService::subscribe(10,['endpoint'=>'legacy-shared','platform'=>'android']);
check(count(PushService::subscriptions(10))===1 && count(PushService::subscriptions(20))===1,'Authenticated re-registration resolves ownership');
PushService::subscribe(20,['endpoint'=>'other-device','platform'=>'android']);
check(count(PushService::subscriptions(20))===2,'Multiple devices for one account supported');
PushService::unsubscribe(20,'other-device');
check(count(PushService::subscriptions(20))===1,'Device-specific logout');
$db->exec('DELETE FROM notifications; DELETE FROM notification_queue');
$db->beginTransaction();
$id=MailService::createMail(30,'Subject','Private body',[10,20,20,30,0],[]);
check($db->query('SELECT recipient_id FROM internal_mail_recipients ORDER BY recipient_id')->fetchAll(PDO::FETCH_COLUMN)===[10,20],'Mail recipient deduplication/exclude sender');
check($db->query('SELECT user_id FROM notifications ORDER BY user_id')->fetchAll(PDO::FETCH_COLUMN)===[10,20],'Only mail recipients notified');
check((int)$db->query('SELECT COUNT(*) FROM notification_queue')->fetchColumn()===2,'One push per mail recipient');
check($db->query('SELECT entity_type FROM notification_queue LIMIT 1')->fetchColumn()==='internal_mail','Push supports mail routing');
check($db->query('SELECT link FROM notification_queue LIMIT 1')->fetchColumn()==='/mail/'.$id,'Mail-specific web link');
$db->rollBack();
check((int)$db->query('SELECT COUNT(*) FROM notifications')->fetchColumn()===0 && (int)$db->query('SELECT COUNT(*) FROM notification_queue')->fetchColumn()===0,'Failed send/attachment rolls back alerts');
$db->beginTransaction();MailService::createMail(30,'Delivered','Body',[10,20],[]);$db->commit();
check((int)$db->query('SELECT COUNT(*) FROM notifications')->fetchColumn()===2,'Successful mail commits alerts');
echo "PASS: team/HR recipient isolation, duplicate rules, inactive/missing managers, Android/iOS/web endpoint ownership, legacy ambiguity, logout, multiple devices, mail deduplication and transactional notification rollback.\n";
